// Test data for standalone runs. The real caller is the main workflow's
// Accounts config. account_id is the full profile URL.
return [
  { json: { platform: 'LinkedIn Profile', channel: 'Brand B', account_id: 'https://www.linkedin.com/in/your-profile/' } },
];

// Common landing point for both entry paths so the normalizer can reference
// ONE upstream node by name. Also accepts a bare handle and turns it into a
// profile URL.
return $input.all().map(item => {
  const id = String(item.json.account_id || '').trim();
  const url = /^https?:\/\//i.test(id) ? id : `https://www.linkedin.com/in/${id.replace(/^\/+|\/+$/g, '')}/`;
  return { json: { ...item.json, account_id: url }, pairedItem: item.pairedItem ?? 0 };
});

// Maps harvestapi/linkedin-profile-posts (Apify) output into the standard row
// schema. Each dataset item IS one post. Public scraping exposes NO impression
// counts, so `views` is always null (the report shows N/A for it).
//
// account_id/channel come from 'Prepare request' via pairedItem, same pattern
// as the TikTok fetcher. Rows are emitted as platform 'LinkedIn' so they land
// in the existing LinkedIn section of the report under the personal channel.

function srcIndex(item, fallback) {
  const pi = item.pairedItem;
  if (typeof pi === 'number') return pi;
  if (Array.isArray(pi) && pi.length) return pi[0].item;
  if (pi && typeof pi === 'object' && pi.item !== undefined) return pi.item;
  return fallback;
}

const items = $input.all();
const first = $('Prepare request').first().json;

// Apify actors with limited permissions can return a demo placeholder instead
// of real data when the account has no access -- fail loudly rather than
// reporting a fake post.
if (items.some(i => i.json && i.json.demo === true)) {
  throw new Error('Apify returned demo data for harvestapi/linkedin-profile-posts. Check the Apify plan/permissions for this actor.');
}

const posts = items.filter(i => i.json && i.json.id && (i.json.content !== undefined || i.json.linkedinUrl));

if (!posts.length) {
  return [{
    json: {
      platform: 'LinkedIn',
      channel: first.channel,
      skipped: true,
      reason: 'No posts returned for the profile (private, empty, or scrape blocked).',
    },
    pairedItem: 0,
  }];
}

function postType(p) {
  if (p.document) return 'Document';
  if (p.postVideo || p.video || (p.media && p.media.type === 'video')) return 'Video';
  if (Array.isArray(p.postImages) && p.postImages.length) return 'Photo';
  if (p.article) return 'Article';
  if (p.poll) return 'Poll';
  if (p.repostedBy || p.repost || p.type === 'repost') return 'Reshare';
  return 'Text';
}

function cleanTitle(text) {
  return String(text || '')
    .replace(/\s+/g, ' ')
    .replace(/\{hashtag\|\\?#\|([^}]+)\}/g, '#$1')
    .trim()
    .slice(0, 100);
}

const num = v => (typeof v === 'number' ? v : (v == null || v === '' ? null : Number(v)));

return posts.map((item, index) => {
  const ctx = $('Prepare request').itemMatching(srcIndex(item, index)).json;
  const p = item.json;
  const eng = p.engagement || {};
  const created = (p.postedAt && (p.postedAt.date || p.postedAt.timestamp)) || null;

  return {
    json: {
      platform: 'LinkedIn',
      channel: ctx.channel,
      account_id: ctx.account_id,
      likes_label: 'Reactions',
      id: String(p.id),
      title: cleanTitle(p.content),
      type: postType(p),
      views: null,
      likes: num(eng.likes),
      comments: num(eng.comments),
      shares: num(eng.shares),
      permalink: p.linkedinUrl || (p.socialContent && p.socialContent.shareUrl) || null,
      created_at: created ? new Date(created).toISOString() : null,
      insights_ok: true,
    },
    pairedItem: 0,
  };
});
